function getAllQuestions() {
  var all = [];
  Object.keys(EXAM_BANKS).forEach(function(key) {
    var bank = EXAM_BANKS[key];
    bank.questions.forEach(function(q) {
      all.push({ bank: key, bankName: bank.shortName, question: q });
    });
  });
  return all;
}